// Visible proof something runs after the Agent, for the demo. Deliberately
// a pass-through, not a reshape -- the frontend proxy (lib/agent/ask-via-n8n.ts)
// expects the Agent's exact { output, intermediateSteps } shape unchanged.
// n8n's own chatTrigger metadata warns against ending this chain on a node
// whose output ISN'T that shape when responseMode is lastNode/responseNode.
console.log(`[Ask Cadence] answered in this execution — ${($json.intermediateSteps || []).length} run_sql call(s)`);
return [{ json: { ...$json, respondedAt: new Date().toISOString() } }];
